// Smooth (anti-aliased) Rajdhani fonts, generated by tools/make_fonts.py.
//
// TFT_eSPI can only have one smooth font loaded at a time, and while one is
// loaded the numbered built-in fonts (1, 2, 4...) are ignored. fonts::use()
// keeps track of what's loaded and only swaps when needed. Loading a font
// from flash just reads its glyph table (~1 KB of RAM), so swapping is quick.
#pragma once
#include <TFT_eSPI.h>

namespace fonts {

enum class Id {
  BuiltIn,   // back to TFT_eSPI's numbered fonts
  Small,     // 16 px  date, place, labels
  Medium,    // 24 px  greeting, AM/PM
  Temp,      // 40 px  temperature (digits, minus, degree sign, F, C only)
  Clock,     // 56 px  clock (digits, colon, minus only)
};

void use(TFT_eSPI& tft, Id id);

}  // namespace fonts
